/**
 * AI column mapping + deterministic value copying.
 * The AI only decides WHICH column is WHICH field. Every learner value is then copied from the
 * spreadsheet by code, so no grade is ever generated by the model.
 */
import { AiError, callAi, type Caller, type Tool } from '@/server/core/llm';
import { gradeColumnWarnings, learnerColumnWarnings, listRows } from '@/server/import/checks';
import { verifyClassDetails } from '@/server/import/details';
import { previewText, titleText, type Grid } from '@/server/import/extract';
import type { Student } from '@/lib/domain/types';

export const LEARNER_FIELDS = ['roll', 'name', 'middleName', 'age', 'sex', 'lrn', 'birthdate'];
export const CLASS_FIELDS = ['className', 'strand', 'gradeLevel', 'year', 'term', 'section', 'studentStatus', 'graduationStatus',
  'teacher', 'principal', 'schoolName', 'department', 'region', 'division', 'schoolAddress', 'track'];
const PERIODS = ['q1', 'q2', 'q3', 'q4', 'final'];
const ATT_FIELDS = ['schoolDays', 'present', 'absent'];
const OV_PERIODS = ['q1', 'q2', 'q3', 'q4'];
const FOOTER = /^((class|general|overall|section|grand)\s+)?(total|average|ave\.?|mean|passed|failed|remarks?|prepared by|checked by|noted by|certified correct)\b/i;

export class MappingError extends Error {
  /** config: server not set up, file: layout not understood, ai: service failure */
  constructor(message: string, public kind: 'config' | 'file' | 'ai' = 'ai') {
    super(message);
  }
}

export interface ImportSchema {
  subjects: { key: string; name: string; semester: string }[];
  months: string[];
  coreValues: string[];
  transferFields: string[];
}

export function parseSchema(text: string): ImportSchema {
  try {
    const s = JSON.parse(text);
    if (!['subjects', 'months', 'coreValues', 'transferFields'].every((k) => k in s)) throw new Error('missing');
    if (!s.subjects.every((x: Record<string, unknown>) => 'key' in x && 'name' in x && 'semester' in x)) throw new Error('subjects');
    return s;
  } catch {
    throw new MappingError('The import schema is missing or invalid.', 'file');
  }
}

export function allowedFields(schema: ImportSchema): Set<string> {
  const fields = new Set<string>(LEARNER_FIELDS);
  schema.subjects.forEach((s) => PERIODS.forEach((p) => fields.add(`grade:${s.key}:${p}`)));
  schema.months.forEach((m) => ATT_FIELDS.forEach((f) => fields.add(`att:${m}:${f}`)));
  schema.coreValues.forEach((v) => OV_PERIODS.forEach((p) => fields.add(`ov:${v}:${p}`)));
  schema.transferFields.forEach((t) => fields.add(`transfer:${t}`));
  return fields;
}

export function buildTool(): Tool {
  return {
    name: 'submit_column_mapping',
    description: 'Report where each learner field lives in the spreadsheet. Never invent values.',
    input_schema: {
      type: 'object',
      properties: {
        header_row: { type: 'integer', description: 'Row index of the (last) header row' },
        first_data_row: { type: 'integer', description: 'Row index of the first learner row' },
        columns: { type: 'array', items: { type: 'object', properties: { col: { type: 'integer' }, field: { type: 'string' } }, required: ['col', 'field'] } },
        class_details: { type: 'object', description: `Class-level values read from title rows or a constant column. Allowed keys: ${CLASS_FIELDS.join(', ')}`, additionalProperties: { type: 'string' } },
        warnings: { type: 'array', items: { type: 'string' } }
      },
      required: ['header_row', 'first_data_row', 'columns']
    }
  };
}

const CLASS_HELP = `  className   class title as shown, e.g. "Grade 12 - ABM 1" (only if the sheet writes one)
  schoolName  name of the school;  schoolAddress  street/city line;  region, division, department as written (e.g. "Region VI", "Division of Iloilo")
  year        school year, e.g. 2024-2025;  term  semester or grading period as written (e.g. "1st Semester");  gradeLevel  digits only, 11 or 12
  strand      e.g. ABM, STEM, HUMSS, GAS, TVL;  track  e.g. Academic;  section  section name only
  teacher     the class ADVISER's name;  principal  the school head's name (not the teacher, not a learner)
  studentStatus, graduationStatus  only if a column/title states them`;

export function buildPrompt(schema: ImportSchema, grid: Grid): string {
  const subjects = schema.subjects.map((s) => `- ${s.key}  =  ${s.name}  (semester: ${s.semester})`).join('\n');
  return `You map a Philippine Senior High School class gradebook spreadsheet onto a fixed schema.

You see only the top rows of the sheet. Row and column indexes are 0-based and shown in the table header.
Call submit_column_mapping exactly once.

Field names you may use in \`columns[].field\`:
- Learner fields, written EXACTLY as one of these words with no prefix: ${LEARNER_FIELDS.join(', ')}  (name = full learner name; birthdate = date of birth)
- Grades: grade:<subjectKey>:<period>   period is one of q1,q2,q3,q4,final.
  \`final\` is that subject's semester final grade. Subjects 1st semester use q1,q2; 2nd semester use q3,q4.
- Attendance: att:<month>:<schoolDays|present|absent>   months: ${schema.months.join(', ')}
- Core values: ov:<value>:<q1..q4>   values: ${schema.coreValues.join(', ')}
- Transfer: transfer:<field>   fields: ${schema.transferFields.join(', ')}

Subject keys:
${subjects}

Rules:
- Map a column only if you are confident. Skip unrelated columns (totals, remarks, signatures).
- Headers may be spread over several rows (subject on one row, Q1/Q2 beneath) and may use abbreviations, Filipino names or different order.
- Put class-level facts found in title rows (school name, department, region, division, school address, track/strand, grade level, section, adviser, principal) into \`class_details\`.
- If a subject, period or learner column cannot be found, do not guess; add a short entry to \`warnings\`.
- Never output grade values. You only describe the layout.

Title area, full text (class details are usually here, sometimes as "Label: value" in one cell):
${titleText(grid)}

Sheet "${grid.sheet}" (top rows, for the columns):
${previewText(grid)}
`;
}

const num = (value: unknown): [number | null, boolean] => {
  const t = String(value ?? '').trim();
  if (['', '-', '—', 'n/a', 'N/A'].includes(t)) return [null, true];
  const n = Number(t.replace(/%$/, ''));
  return Number.isNaN(n) ? [null, false] : [n, true];
};
const wholeNumber = (value: unknown): [number | null, boolean] => {
  const [n, ok] = num(value);
  if (!ok) return [null, false];
  if (n === null) return [null, true];
  return Number.isInteger(n) && n >= 0 ? [n, true] : [null, false];
};

export function lrnText(value: unknown): string {
  let t = String(value ?? '').trim();
  if (/^\d+\.0+$/.test(t)) t = t.split('.')[0];
  if (/^\d(\.\d+)?[eE]\+?\d+$/.test(t)) t = BigInt(Math.round(Number(t))).toString();
  return t;
}

const sexText = (value: unknown) => {
  const t = String(value ?? '').trim().toLowerCase();
  if (['m', 'male', 'lalaki', 'boy'].includes(t)) return 'Male';
  if (['f', 'female', 'babae', 'girl'].includes(t)) return 'Female';
  return String(value ?? '').trim();
};

/** Tolerate small formatting slips from the model, e.g. 'Learner:name' or ' Grade:x:q1 '. */
export function cleanField(value: unknown): string {
  let text = String(value).replace(/\s+/g, '');
  text = text.replace(/^(learner|student)[:.]/i, '');
  const idx = text.indexOf(':');
  const head = idx >= 0 ? text.slice(0, idx) : text;
  const rest = idx >= 0 ? text.slice(idx) : '';
  return ['grade', 'att', 'ov', 'transfer'].includes(head.toLowerCase()) ? head.toLowerCase() + rest : text;
}

export interface Mapping { columns: Map<number, string>; first: number; details: Record<string, string> }

export function validateMapping(raw: Record<string, unknown>, schema: ImportSchema, width: number, nrows: number): { mapping: Mapping; warnings: string[] } {
  const allowed = allowedFields(schema);
  const warnings = ((raw.warnings as unknown[]) ?? []).map(String).filter((w) => w.trim());
  const cols = new Map<number, string>();
  const used = new Set<string>();
  for (const item of (raw.columns as { col: unknown; field: unknown }[]) ?? []) {
    const col = Number(item?.col);
    const name = item?.field == null ? '' : cleanField(item.field);
    if (!Number.isInteger(col)) continue;
    if (col < 0 || col >= width || !allowed.has(name)) { warnings.push(`Ignored an unusable mapping ('${name}' -> column ${col}).`); continue; }
    if (used.has(name)) { warnings.push(`Field '${name}' was mapped to more than one column; kept the first.`); continue; }
    cols.set(col, name); used.add(name);
  }
  if (!used.has('name')) throw new MappingError('Could not find the learner name column in this file.', 'file');
  const first = raw.first_data_row;
  if (typeof first !== 'number' || !Number.isInteger(first) || first < 0 || first >= nrows) throw new MappingError('Could not tell where the learner rows start.', 'file');
  const details: Record<string, string> = {};
  Object.entries((raw.class_details as Record<string, unknown>) ?? {}).forEach(([k, v]) => {
    if (CLASS_FIELDS.includes(k) && String(v).trim()) details[k] = String(v).trim();
  });
  return { mapping: { columns: cols, first, details }, warnings };
}

export function newStudent(id: number, name: string, schema: Pick<ImportSchema, 'subjects' | 'coreValues'>): Student {
  return {
    id, roll: '', name: name.slice(0, 80), middleName: '', age: '', sex: '', lrn: '', birthdate: '',
    grades: Object.fromEntries(schema.subjects.map((s) => [s.key, {}])),
    attendance: { present: null, total: null, months: {}, schoolDays: {}, absent: {} },
    transfer: {}, observedValues: Object.fromEntries(schema.coreValues.map((v) => [v, {}])),
    comment: '', commentReviewed: true, traits: null, nextSteps: null
  };
}

export function applyMapping(grid: Grid, mapping: Mapping, schema: ImportSchema): { students: Student[]; warnings: string[]; counts: ImportCounts } {
  const cols = mapping.columns;
  const nameCol = [...cols.entries()].find(([, f]) => f === 'name')![0];
  const warnings: string[] = [];
  const students: Student[] = [];
  const seenRolls = new Set<string>();
  const footers: number[] = [];
  const nameless: number[] = [];
  let blank = 0;
  for (let r = mapping.first; r < grid.rows.length; r += 1) {
    const row = grid.rows[r];
    const name = nameCol < row.length ? String(row[nameCol]).trim() : '';
    if (!name) {
      if (row.some((c) => String(c ?? '').trim() !== '')) nameless.push(r + 1); else blank += 1;
      continue;
    }
    if (FOOTER.test(name)) { footers.push(r + 1); continue; } // a total or signature row, not the end of the list
    const stu = newStudent(students.length + 1, name, schema);
    for (const [c, f] of cols) {
      const cell = c < row.length ? row[c] : '';
      const parts = f.split(':');
      if (LEARNER_FIELDS.includes(f)) {
        if (f === 'name') continue;
        const value = f === 'lrn' ? lrnText(cell) : f === 'sex' ? sexText(cell) : String(cell).trim();
        (stu as unknown as Record<string, string>)[f] = value;
      } else if (parts[0] === 'grade') {
        const [n, ok] = num(cell);
        if (!ok) warnings.push(`${name}: '${String(cell).slice(0, 20)}' in ${f} is not a number; left blank.`);
        (stu.grades[parts[1]] as Record<string, number | null>)[parts[2]] = n;
      } else if (parts[0] === 'att') {
        const [n, ok] = wholeNumber(cell);
        if (!ok) warnings.push(`${name}: '${String(cell).slice(0, 20)}' in ${f} is not a whole number; left blank.`);
        const bucket = ({ schoolDays: 'schoolDays', present: 'months', absent: 'absent' } as const)[parts[2] as 'schoolDays'];
        stu.attendance[bucket][parts[1]] = n;
      } else if (parts[0] === 'ov') {
        stu.observedValues[parts[1]][parts[2]] = String(cell).trim().toUpperCase();
      } else if (parts[0] === 'transfer') {
        stu.transfer[parts[1]] = String(cell).trim();
      }
    }
    // make sure every expected key exists so the UI never sees undefined
    schema.subjects.forEach((s) => {
      [...(s.semester === 'first' ? ['q1', 'q2'] : ['q3', 'q4']), 'final'].forEach((p) => {
        const g = stu.grades[s.key] as Record<string, number | null>;
        if (!(p in g)) g[p] = null;
      });
    });
    const days = Object.values(stu.attendance.schoolDays).filter((v): v is number => Number.isInteger(v));
    const pres = Object.values(stu.attendance.months).filter((v): v is number => Number.isInteger(v));
    if (days.length) { stu.attendance.total = days.reduce((a, b) => a + b, 0); stu.attendance.present = pres.reduce((a, b) => a + b, 0); }
    let roll = stu.roll || String(students.length + 1).padStart(2, '0');
    while (seenRolls.has(roll.toLowerCase())) { roll += '*'; warnings.push(`${name}: duplicate roll number; adjusted to ${roll}.`); }
    seenRolls.add(roll.toLowerCase());
    stu.roll = roll;
    students.push(stu);
  }
  if (!students.length) throw new MappingError('No learner rows were found below the header.', 'file');
  if (footers.length) warnings.push(`${footers.length} total/signature row${footers.length === 1 ? '' : 's'} ignored (${listRows(footers)}).`);
  if (nameless.length) warnings.push(`${nameless.length} row${nameless.length === 1 ? ' has' : 's have'} data but no learner name, so ${nameless.length === 1 ? 'it was' : 'they were'} skipped (${listRows(nameless)}).`);
  const skipped = footers.length + nameless.length;
  const counts = { found: students.length + skipped, imported: students.length, skipped, blank };
  warnings.unshift(`${counts.found} row${counts.found === 1 ? '' : 's'} with content found below the header (${blank} empty row${blank === 1 ? '' : 's'} ignored): ${students.length} learners imported, ${skipped} skipped.`);
  return { students, warnings, counts };
}

/** Human label per mapped column: the up-to-2 header rows above the data, joined. */
export function headerLabels(grid: Grid, firstDataRow: number, columns: Map<number, string>): Map<number, string> {
  const cell = (r: number, c: number) => (c < grid.rows[r].length ? String(grid.rows[r][c]).trim() : '');
  const need = Math.min(2, columns.size);
  const rows: number[] = [];
  for (let r = Math.max(0, firstDataRow - 2); r < firstDataRow; r += 1) {
    if ([...columns.keys()].filter((c) => cell(r, c)).length >= need) rows.push(r);
  }
  const out = new Map<number, string>();
  for (const c of columns.keys()) {
    const parts: string[] = [];
    for (const r of rows) {
      let text = '';
      for (let k = c; k > Math.max(-1, c - 3); k -= 1) { const v = cell(r, k); if (v) { text = v; break; } }
      if (text && !parts.includes(text)) parts.push(text);
    }
    out.set(c, parts.join(' · '));
  }
  return out;
}

/** Row accounting for one import: every row with content is either imported or skipped (and listed in the warnings). */
export interface ImportCounts { found: number; imported: number; skipped: number; blank: number }

export interface ImportResult {
  counts?: ImportCounts;
  students: Student[];
  classDetails: Record<string, string>;
  mapping: { col: number; header: string; field: string }[];
  warnings: string[];
  sheet: string;
  schoolLogo?: string;
}

export async function runImport(grid: Grid, schema: ImportSchema, caller: Caller = callAi): Promise<ImportResult> {
  let raw: Record<string, unknown>;
  try {
    raw = await caller(buildPrompt(schema, grid), buildTool());
  } catch (error) {
    if (error instanceof AiError) throw new MappingError(error.message, error.kind === 'config' ? 'config' : 'ai');
    throw error;
  }
  const { mapping, warnings } = validateMapping(raw, schema, grid.rows[0].length, grid.rows.length);
  const checked = verifyClassDetails(mapping.details, grid); // drop details the sheet does not contain; read labelled cells by code
  mapping.details = checked.details;
  warnings.push(...checked.warnings);
  const { students, warnings: applyWarnings, counts } = applyMapping(grid, mapping, schema);
  const labels = headerLabels(grid, mapping.first, mapping.columns);
  const colOf = (field: string) => [...mapping.columns.entries()].find(([, f]) => f === field)?.[0];
  warnings.push(
    ...learnerColumnWarnings(grid, mapping.first, { name: colOf('name'), lrn: colOf('lrn') }),
    ...gradeColumnWarnings(grid, mapping.first, [...mapping.columns.entries()].filter(([, f]) => f.startsWith('grade:')).map(([col, f]) => ({ col, label: `${labels.get(col) || f}` })))
  );
  if (grid.skippedSheets.length) warnings.push(`Other sheets were not read: ${grid.skippedSheets.join(', ')}.`);
  return {
    students, counts, classDetails: mapping.details, sheet: grid.sheet,
    mapping: [...mapping.columns.entries()].sort((a, b) => a[0] - b[0]).map(([col, field]) => ({ col, header: labels.get(col) ?? '', field })),
    warnings: [...warnings, ...applyWarnings.slice(0, 50)]
  };
}
